-- Dairy Farm Management Software - complete MySQL schema
-- Target: MySQL 8.4 / database dairy_farm
CREATE DATABASE IF NOT EXISTS `dairy_farm` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `dairy_farm`;

CREATE TABLE IF NOT EXISTS companies(
 company_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(200) NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS farms(
 farm_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,
 location VARCHAR(255),contact VARCHAR(255),status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(company_id),CONSTRAINT fk_farms_company FOREIGN KEY(company_id) REFERENCES companies(company_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sheds(
 shed_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,
 capacity INT UNSIGNED NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(farm_id) REFERENCES farms(farm_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS animal_groups(
 group_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,shed_id BIGINT UNSIGNED NULL,
 name VARCHAR(150) NOT NULL,animal_type VARCHAR(50) NOT NULL DEFAULT 'COW',status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(farm_id) REFERENCES farms(farm_id),FOREIGN KEY(shed_id) REFERENCES sheds(shed_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS breeds(
 breed_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,active TINYINT(1) NOT NULL DEFAULT 1,
 UNIQUE KEY uq_breeds_name(name)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS animals(
 animal_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_code VARCHAR(50) NOT NULL,
 name VARCHAR(150),breed_id BIGINT UNSIGNED NULL,sex VARCHAR(10) NOT NULL,dob DATE NULL,
 status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',group_id BIGINT UNSIGNED NULL,dam_id BIGINT UNSIGNED NULL,sire_id BIGINT UNSIGNED NULL,
 purchase_date DATE NULL,purchase_price DECIMAL(14,2) NULL,photo VARCHAR(500),notes TEXT,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_animal_farm_code(farm_id,animal_code),INDEX(farm_id),INDEX(status),INDEX(group_id),
 FOREIGN KEY(farm_id) REFERENCES farms(farm_id),FOREIGN KEY(breed_id) REFERENCES breeds(breed_id) ON DELETE SET NULL,
 FOREIGN KEY(group_id) REFERENCES animal_groups(group_id) ON DELETE SET NULL,
 FOREIGN KEY(dam_id) REFERENCES animals(animal_id) ON DELETE SET NULL,FOREIGN KEY(sire_id) REFERENCES animals(animal_id) ON DELETE SET NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS animal_identifications(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,animal_id BIGINT UNSIGNED NOT NULL,type VARCHAR(50) NOT NULL,value VARCHAR(150) NOT NULL,
 is_primary TINYINT(1) NOT NULL DEFAULT 0,active_from DATE NULL,active_to DATE NULL,INDEX(type,value),INDEX(animal_id),
 FOREIGN KEY(animal_id) REFERENCES animals(animal_id) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS animal_status_history(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,animal_id BIGINT UNSIGNED NOT NULL,old_status VARCHAR(20),new_status VARCHAR(20) NOT NULL,
 reason VARCHAR(500),changed_by BIGINT UNSIGNED NULL,changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 INDEX(animal_id),FOREIGN KEY(animal_id) REFERENCES animals(animal_id) ON DELETE RESTRICT
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS animal_code_sequences(
 farm_id BIGINT UNSIGNED PRIMARY KEY,prefix VARCHAR(20) NOT NULL DEFAULT 'AN-',next_number BIGINT UNSIGNED NOT NULL DEFAULT 1,
 FOREIGN KEY(farm_id) REFERENCES farms(farm_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS animal_photos(
 photo_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,animal_id BIGINT UNSIGNED NOT NULL,file_type VARCHAR(50) NOT NULL,image_data LONGBLOB NOT NULL,
 file_size INT UNSIGNED NOT NULL,is_primary TINYINT(1) NOT NULL DEFAULT 0,uploaded_by BIGINT UNSIGNED NULL,uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 INDEX(animal_id),FOREIGN KEY(animal_id) REFERENCES animals(animal_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS roles(role_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description TEXT);
CREATE TABLE IF NOT EXISTS users(
 user_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,phone VARCHAR(50),
 email VARCHAR(255) UNIQUE,password_hash VARCHAR(255),auth_provider VARCHAR(50) NOT NULL DEFAULT 'LOCAL',status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE',
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(company_id) REFERENCES companies(company_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_roles(user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,role_id),
 FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES roles(role_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS permissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(150) NOT NULL UNIQUE,description TEXT);
CREATE TABLE IF NOT EXISTS role_permissions(role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),
 FOREIGN KEY(role_id) REFERENCES roles(role_id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS farm_user_access(user_id BIGINT UNSIGNED NOT NULL,farm_id BIGINT UNSIGNED NOT NULL,access_level VARCHAR(20) NOT NULL DEFAULT 'VIEW',
 PRIMARY KEY(user_id,farm_id),FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(farm_id) REFERENCES farms(farm_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS api_keys(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,
 key_prefix VARCHAR(20) NOT NULL,key_hash CHAR(64) NOT NULL UNIQUE,scopes TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 expires_at DATETIME NULL,revoked_at DATETIME NULL,INDEX(company_id),FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE SET NULL,FOREIGN KEY(company_id) REFERENCES companies(company_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `milk_records` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,morning DECIMAL(10,3) NOT NULL DEFAULT 0,evening DECIMAL(10,3) NOT NULL DEFAULT 0,third DECIMAL(10,3) NOT NULL DEFAULT 0,total DECIMAL(10,3) NOT NULL DEFAULT 0,fat DECIMAL(6,2),protein DECIMAL(6,2),snf DECIMAL(6,2),scc DECIMAL(12,2),rejected DECIMAL(10,3) NOT NULL DEFAULT 0,notes TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `lactations` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,lactation_number INT NOT NULL,calving_date DATE,start_date DATE,peak_milk DECIMAL(10,3),peak_date DATE,current_milk DECIMAL(10,3),days_in_milk INT,total_milk DECIMAL(12,3) NOT NULL DEFAULT 0,dry_date DATE,end_date DATE, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `breeding_events` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(30) NOT NULL,event_date DATE NOT NULL,ai_date DATE,bull_or_semen VARCHAR(200),technician VARCHAR(150),service_number INT NOT NULL DEFAULT 1,pregnancy_diagnosis_date DATE,pregnancy_result VARCHAR(30),expected_calving_date DATE,notes TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `pregnancies` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,diagnosis_date DATE NOT NULL,result VARCHAR(30) NOT NULL DEFAULT 'PENDING',expected_calving_date DATE,method VARCHAR(100),notes TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `calvings` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,dam_id BIGINT UNSIGNED NOT NULL,sire_id BIGINT UNSIGNED,expected_date DATE NOT NULL,actual_date DATE,difficulty VARCHAR(50),calf_count INT NOT NULL DEFAULT 1,calf_sex VARCHAR(20),birth_weight DECIMAL(8,2),calf_id BIGINT UNSIGNED,colostrum_given TINYINT(1) NOT NULL DEFAULT 0,complications TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `growth_records` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,weight_kg DECIMAL(8,2),height_cm DECIMAL(8,2),heart_girth_cm DECIMAL(8,2),body_length_cm DECIMAL(8,2),notes TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `health_records` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,problem VARCHAR(255) NOT NULL,symptoms TEXT,diagnosis TEXT,veterinarian VARCHAR(150),treatment TEXT,medicine_id BIGINT UNSIGNED,dose DECIMAL(10,3),dose_unit VARCHAR(50),duration_days INT,cost DECIMAL(14,2),recovery_date DATE,remarks TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `diseases` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,description TEXT,active TINYINT(1) NOT NULL DEFAULT 1, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `medicines` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,name VARCHAR(200) NOT NULL,manufacturer VARCHAR(200),batch VARCHAR(100),quantity DECIMAL(14,3) NOT NULL DEFAULT 0,purchase_price DECIMAL(14,2) NOT NULL DEFAULT 0,expiry DATE,unit VARCHAR(30) NOT NULL DEFAULT 'unit',supplier VARCHAR(200),milk_withdrawal_days INT NOT NULL DEFAULT 0,meat_withdrawal_days INT NOT NULL DEFAULT 0, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `treatments` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,medicine_id BIGINT UNSIGNED,start_date DATE NOT NULL,end_date DATE,quantity_used DECIMAL(14,3) NOT NULL DEFAULT 0,dose VARCHAR(100),milk_withdrawal_until DATE,meat_withdrawal_until DATE,notes TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `vaccinations` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED,group_id BIGINT UNSIGNED,vaccine VARCHAR(200) NOT NULL,date DATE NOT NULL,batch VARCHAR(100),manufacturer VARCHAR(200),next_due_date DATE,veterinarian VARCHAR(150), INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `feeds` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,name VARCHAR(200) NOT NULL,unit VARCHAR(30) NOT NULL DEFAULT 'kg',purchase_price DECIMAL(14,2) NOT NULL DEFAULT 0,supplier VARCHAR(200),dry_matter_percent DECIMAL(6,2),protein_percent DECIMAL(6,2),energy_mcal DECIMAL(8,3),active TINYINT(1) NOT NULL DEFAULT 1, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `rations` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,name VARCHAR(200) NOT NULL,animal_group VARCHAR(100) NOT NULL,effective_from DATE NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,notes TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `ration_items` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ration_id BIGINT UNSIGNED NOT NULL,feed_id BIGINT UNSIGNED NOT NULL,quantity_kg_per_head DECIMAL(10,3) NOT NULL, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `feed_consumption` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,feed_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED,group_id BIGINT UNSIGNED,date DATE NOT NULL,quantity DECIMAL(14,3) NOT NULL,cost DECIMAL(14,2) NOT NULL DEFAULT 0, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `feed_purchases` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,feed_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED,date DATE NOT NULL,quantity DECIMAL(14,3) NOT NULL,unit_price DECIMAL(14,2) NOT NULL,total DECIMAL(14,2) NOT NULL,reference VARCHAR(100), INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `animal_purchases` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,seller VARCHAR(200),date DATE NOT NULL,purchase_price DECIMAL(14,2) NOT NULL,transport_cost DECIMAL(14,2) NOT NULL DEFAULT 0,veterinary_cost DECIMAL(14,2) NOT NULL DEFAULT 0,inspection TEXT,health_status VARCHAR(100),previous_farm VARCHAR(200),quarantine_days INT,landed_cost DECIMAL(14,2) NOT NULL,documents TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `animal_sales` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,buyer VARCHAR(200),date DATE NOT NULL,sale_price DECIMAL(14,2) NOT NULL,weight_kg DECIMAL(10,2),reason VARCHAR(100),cost_basis DECIMAL(14,2),profit_loss DECIMAL(14,2), INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `mortalities` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,age_at_death VARCHAR(50),lactation VARCHAR(50),pregnancy_status VARCHAR(50),disease_history TEXT,suspected_cause VARCHAR(255),confirmed_cause VARCHAR(255),treatment TEXT,value DECIMAL(14,2),post_mortem_notes TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `expenses` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,category VARCHAR(100) NOT NULL,amount DECIMAL(14,2) NOT NULL,payee VARCHAR(200),description TEXT,payment_method VARCHAR(50),receipt_path VARCHAR(500), INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `income` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,category VARCHAR(100) NOT NULL,amount DECIMAL(14,2) NOT NULL,description TEXT,animal_id BIGINT UNSIGNED,quantity DECIMAL(14,3),unit_price DECIMAL(14,2), INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `customers` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,name VARCHAR(200) NOT NULL,phone VARCHAR(50),address VARCHAR(500),daily_quantity DECIMAL(10,3) NOT NULL DEFAULT 0,rate DECIMAL(10,2) NOT NULL DEFAULT 0,delivery_notes TEXT,balance DECIMAL(14,2) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `milk_sales` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED,date DATE NOT NULL,quantity DECIMAL(14,3) NOT NULL,price_per_liter DECIMAL(10,2) NOT NULL,total DECIMAL(14,2) NOT NULL,payment_status VARCHAR(30), INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `customer_payments` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,amount DECIMAL(14,2) NOT NULL,method VARCHAR(50),reference VARCHAR(100), INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `suppliers` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,name VARCHAR(200) NOT NULL,phone VARCHAR(50),address VARCHAR(500),products TEXT,balance DECIMAL(14,2) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `supplier_payments` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,amount DECIMAL(14,2) NOT NULL,method VARCHAR(50),reference VARCHAR(100), INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `tasks` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,animal_id BIGINT UNSIGNED,group_id BIGINT UNSIGNED,due_date DATE NOT NULL,assigned_user_id BIGINT UNSIGNED,priority VARCHAR(20) NOT NULL DEFAULT 'MEDIUM',status VARCHAR(20) NOT NULL DEFAULT 'OPEN',completed_at DATETIME,type VARCHAR(50) NOT NULL DEFAULT 'GENERAL',notes TEXT, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `notifications` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED,type VARCHAR(30) NOT NULL,title VARCHAR(255) NOT NULL,message TEXT NOT NULL,entity_type VARCHAR(100),entity_id BIGINT UNSIGNED,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `attachments` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farm_id BIGINT UNSIGNED NOT NULL,entity_type VARCHAR(100) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,file_name VARCHAR(255) NOT NULL,content_type VARCHAR(100) NOT NULL,size_bytes BIGINT NOT NULL,storage_path VARCHAR(500) NOT NULL,uploaded_by BIGINT UNSIGNED NOT NULL,uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(farm_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `audit_logs` (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,farm_id BIGINT UNSIGNED,action VARCHAR(30) NOT NULL,entity_type VARCHAR(100) NOT NULL,entity_id BIGINT UNSIGNED,old_value LONGTEXT,new_value LONGTEXT,timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ip_address VARCHAR(64), INDEX(farm_id)) ENGINE=InnoDB;

